// ============================================================
// Icamax op_kernel
// BLAS Level 1: 复数向量最大绝对值索引查找
// 计算: argmax_i |Re(x[i*incx])| + |Im(x[i*incx])|, 返回 1-based int32 索引
// ============================================================

#include "kernel_operator.h"

constexpr int32_t BUFFER_NUM = 2;

template <typename T>  // T = float (complex64) or double (complex128)
class KernelIcamax {
public:
    __aicore__ inline KernelIcamax() {}

    __aicore__ inline void Init(GM_ADDR x, GM_ADDR output,
                                 int64_t totalLength, int64_t incx,
                                 int64_t tileLength)
    {
        this->totalLength = totalLength;
        this->incx = incx;
        this->tileLength = tileLength;
        this->maxVal = static_cast<T>(-3.402823466e+38);  // 负无穷近似值
        this->maxIdx = -1;

        // GlobalTensor: 输入复数向量, 按 T 分量访问 (2 * totalLength * incx 个 T 元素)
        xGm.SetGlobalBuffer(reinterpret_cast<__gm__ T *>(x), 2 * totalLength * incx);
        outGm.SetGlobalBuffer(reinterpret_cast<__gm__ int32_t *>(output), 1);

        // UB: 输入缓冲区 (BUFFER_NUM=2 double buffer)
        // 每次加载 tileLength*incx 个复数 → 2*tileLength*incx 个 T 分量
        int64_t bufSize = 2 * tileLength * incx * sizeof(T);
        pipe.InitBuffer(inQueueX, BUFFER_NUM, bufSize);

        // UB: 输出缓冲区 (1 个 int32)
        pipe.InitBuffer(outBuf, sizeof(int32_t));
    }

    __aicore__ inline void Process()
    {
        int64_t tileNum = (this->totalLength + this->tileLength - 1) / this->tileLength;

        for (int64_t i = 0; i < tileNum; ++i) {
            int64_t tileStart = i * this->tileLength;
            int64_t curTileLen = this->tileLength;
            if (i == tileNum - 1) {
                curTileLen = this->totalLength - tileStart;
            }
            // 对齐 curTileLen 到 32B 边界 (用于 DataCopyPad 搬移)
            int64_t alignNum = 32 / static_cast<int64_t>(sizeof(T));
            if (alignNum < 1) { alignNum = 1; }
            int64_t alignedLen = ((curTileLen * incx + alignNum - 1) / alignNum) * alignNum;

            CopyIn(i, alignedLen);
            Compute(i, curTileLen, tileStart);
        }

        CopyOut();
    }

private:
    __aicore__ inline void CopyIn(int64_t progress, int64_t alignedLen)
    {
        // 加载 alignedLen 个复数 → 2*alignedLen 个 T 分量
        int64_t floatCount = 2 * alignedLen;
        int64_t gmFloatOffset = progress * this->tileLength * this->incx * 2;

        AscendC::LocalTensor<T> xLocal = inQueueX.AllocTensor<T>();
        AscendC::DataCopyExtParams copyParams{1, static_cast<uint32_t>(floatCount * sizeof(T)), 0, 0};
        AscendC::DataCopyPadExtParams<T> padParams{false, 0, 0, 0};
        AscendC::DataCopyPad(xLocal, xGm[gmFloatOffset], copyParams, padParams);
        inQueueX.EnQue(xLocal);
    }

    __aicore__ inline void Compute(int64_t progress, int64_t curTileLen, int64_t tileStart)
    {
        AscendC::LocalTensor<T> xLocal = inQueueX.DeQue<T>();

        // 逐元素处理: 提取实部/虚部, 计算 |real| + |imag|, 跟踪最大值
        for (int64_t j = 0; j < curTileLen; ++j) {
            // 复数元素在 float 视图中的偏移: 每个复数占 2 个 T
            int64_t idx = 2 * j * this->incx;
            T real = xLocal.GetValue(idx);
            T imag = xLocal.GetValue(idx + 1);

            // 标量 abs: 不能用 std::abs (kernel 禁止 std 函数)
            T absReal = (real < static_cast<T>(0)) ? -real : real;
            T absImag = (imag < static_cast<T>(0)) ? -imag : imag;
            T absSum = absReal + absImag;

            if (absSum > this->maxVal) {
                this->maxVal = absSum;
                this->maxIdx = tileStart + j;
            }
        }

        inQueueX.FreeTensor(xLocal);
    }

    __aicore__ inline void CopyOut()
    {
        // 计算最终 1-based 索引
        int64_t finalIndex = this->maxIdx * this->incx + 1;
        int32_t outputVal = static_cast<int32_t>(finalIndex);

        AscendC::LocalTensor<int32_t> outLocal = outBuf.Get<int32_t>();
        outLocal.SetValue(0, outputVal);

        AscendC::DataCopyExtParams copyParams{1, static_cast<uint32_t>(sizeof(int32_t)), 0, 0};
        AscendC::DataCopyPad(outGm, outLocal, copyParams);
    }

private:
    AscendC::TPipe pipe;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> inQueueX;
    AscendC::TBuf<AscendC::TPosition::VECCALC> outBuf;
    AscendC::GlobalTensor<T> xGm;
    AscendC::GlobalTensor<int32_t> outGm;

    int64_t totalLength;
    int64_t incx;
    int64_t tileLength;

    T maxVal;
    int64_t maxIdx;
};

extern "C" __global__ __aicore__ void icamax(GM_ADDR x, GM_ADDR output,
                                               int64_t totalLength, int64_t incx,
                                               int64_t tileLength, int64_t dtypeSize)
{
    if (dtypeSize == 8) {  // complex64 = 8 bytes
        KernelIcamax<float> op;
        op.Init(x, output, totalLength, incx, tileLength);
        op.Process();
    } else {  // complex128 = 16 bytes
        KernelIcamax<double> op;
        op.Init(x, output, totalLength, incx, tileLength);
        op.Process();
    }
}
